import React, { useState, useEffect } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import { QUESTIONS, GAME_TYPES } from "../constants/questions";
import { storage, STORAGE_KEYS } from "../utils/storage";
import "./GamePage.css";

const GAME_PHASES = {
  INITIAL_COUNTDOWN: "INITIAL_COUNTDOWN",
  QUESTION_ACTIVE: "QUESTION_ACTIVE",
  ANSWER_FEEDBACK: "ANSWER_FEEDBACK",
  NEXT_QUESTION_COUNTDOWN: "NEXT_QUESTION_COUNTDOWN",
  COMPLETED: "COMPLETED",
};

const GamePage = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { userDetails, gameType } = location.state || {};

  const [currentQuestion, setCurrentQuestion] = useState(0);
  const [timer, setTimer] = useState(0);
  const [score, setScore] = useState(0);
  const [userAnswer, setUserAnswer] = useState("");
  const [selectedOption, setSelectedOption] = useState("");
  const [questions, setQuestions] = useState([]);
  const [countdown, setCountdown] = useState(3);
  const [startTime, setStartTime] = useState(0);
  const [isCorrectAnswer, setIsCorrectAnswer] = useState(false);
  const [gamePhase, setGamePhase] = useState(GAME_PHASES.INITIAL_COUNTDOWN);

  // Initialize questions based on game type
  useEffect(() => {
    const allQuestions =
      QUESTIONS[
        gameType === GAME_TYPES.JUMBLE
          ? "jumbleWords"
          : gameType === GAME_TYPES.MCQ
          ? "mcq"
          : "crossword"
      ];

    // Shuffle and select 6 unique questions
    const shuffled = [...allQuestions].sort(() => Math.random() - 0.5);
    const selectedQuestions = shuffled.slice(0, 6);
    setQuestions(selectedQuestions);
  }, [gameType]);

  // Handle different game phases
  useEffect(() => {
    let phaseTimer;

    switch (gamePhase) {
      case GAME_PHASES.INITIAL_COUNTDOWN:
        if (countdown > 0) {
          phaseTimer = setTimeout(() => setCountdown(countdown - 1), 1000);
        } else {
          startQuestion();
        }
        break;

      case GAME_PHASES.NEXT_QUESTION_COUNTDOWN:
        if (countdown > 0) {
          phaseTimer = setTimeout(() => setCountdown(countdown - 1), 1000);
        } else {
          startQuestion();
        }
        break;

      case GAME_PHASES.QUESTION_ACTIVE:
        if (timer > 0) {
          phaseTimer = setTimeout(() => setTimer(timer - 1), 1000);
        } else {
          handleTimeUp();
        }
        break;

      case GAME_PHASES.ANSWER_FEEDBACK:
        // Auto move to next phase after 2 seconds
        phaseTimer = setTimeout(() => {
          if (currentQuestion < questions.length - 1) {
            prepareNextQuestion();
          } else {
            completeGame();
          }
        }, 2000);
        break;

      default:
        break;
    }

    return () => clearTimeout(phaseTimer);
  }, [gamePhase, countdown, timer, currentQuestion, questions.length]);

  const startQuestion = () => {
    setGamePhase(GAME_PHASES.QUESTION_ACTIVE);
    setStartTime(Date.now());
    const questionTimer = gameType === GAME_TYPES.CROSSWORD ? 60 : 10;
    setTimer(questionTimer);
  };

  const handleTimeUp = () => {
    setIsCorrectAnswer(false);
    setGamePhase(GAME_PHASES.ANSWER_FEEDBACK);
  };

  const calculateScore = (answerTime) => {
    const timeTaken = (Date.now() - startTime) / 1000;
    const baseScore = 100;
    const timeBonus = Math.max(0, 10 - timeTaken) * 10;
    return baseScore + timeBonus;
  };

  const handleSubmit = () => {
    if (gamePhase !== GAME_PHASES.QUESTION_ACTIVE) return;

    const currentQ = questions[currentQuestion];
    let isCorrect = false;

    if (gameType === GAME_TYPES.JUMBLE) {
      isCorrect =
        userAnswer.trim().toUpperCase() === currentQ.correct.toUpperCase();
    } else if (gameType === GAME_TYPES.MCQ) {
      isCorrect = selectedOption === currentQ.correct;
    } else if (gameType === GAME_TYPES.CROSSWORD) {
      isCorrect =
        userAnswer.trim().toUpperCase() === currentQ.answer.toUpperCase();
    }

    setIsCorrectAnswer(isCorrect);

    if (isCorrect) {
      const questionScore = calculateScore();
      setScore((prev) => prev + questionScore);
    }

    setGamePhase(GAME_PHASES.ANSWER_FEEDBACK);
  };

  const prepareNextQuestion = () => {
    const nextQuestionIndex = currentQuestion + 1;

    // Reset inputs for next question
    setUserAnswer("");
    setSelectedOption("");
    setCurrentQuestion(nextQuestionIndex);

    // Check if we should show countdown for next question
    // Show countdown for questions 1-5, but not for question 6
    if (nextQuestionIndex < questions.length - 1) {
      setGamePhase(GAME_PHASES.NEXT_QUESTION_COUNTDOWN);
      setCountdown(3);
    } else {
      // For the last question, go directly without countdown
      startQuestion();
    }
  };

  const completeGame = () => {
    setGamePhase(GAME_PHASES.COMPLETED);

    // Save score
    const gameData = {
      userDetails,
      gameType,
      score,
      timestamp: new Date().toISOString(),
      totalQuestions: questions.length,
    };

    const existingScores = storage.getItem(STORAGE_KEYS.SCORES) || [];
    const existingUserData = storage.getItem(STORAGE_KEYS.USER_DATA) || [];

    storage.setItem(STORAGE_KEYS.SCORES, [...existingScores, gameData]);
    storage.setItem(STORAGE_KEYS.USER_DATA, [...existingUserData, userDetails]);
  };

  const getOptionClassName = (option) => {
    if (gamePhase !== GAME_PHASES.ANSWER_FEEDBACK) {
      return `option-btn ${selectedOption === option ? "selected" : ""}`;
    }

    if (option === questions[currentQuestion].correct) {
      return "option-btn correct-answer";
    } else if (option === selectedOption && !isCorrectAnswer) {
      return "option-btn wrong-answer";
    } else {
      return "option-btn";
    }
  };

  const renderQuestion = () => {
    if (!questions.length || currentQuestion >= questions.length) return null;

    const question = questions[currentQuestion];

    switch (gameType) {
      case GAME_TYPES.JUMBLE:
        return (
          <div className="jumble-question">
            <h2>Unscramble the Word</h2>
            <div className="jumbled-word">{question.jumbled}</div>
            <input
              type="text"
              value={userAnswer}
              onChange={(e) => setUserAnswer(e.target.value)}
              placeholder="Enter the correct word"
              className="answer-input"
              disabled={gamePhase === GAME_PHASES.ANSWER_FEEDBACK}
            />
          </div>
        );

      case GAME_TYPES.MCQ:
        return (
          <div className="mcq-question">
            <h2>{question.question}</h2>
            <div className="options-container">
              {question.options.map((option, index) => (
                <button
                  key={index}
                  className={getOptionClassName(option)}
                  onClick={() =>
                    gamePhase === GAME_PHASES.QUESTION_ACTIVE &&
                    setSelectedOption(option)
                  }
                  disabled={gamePhase === GAME_PHASES.ANSWER_FEEDBACK}
                >
                  {option}
                </button>
              ))}
            </div>
          </div>
        );

      case GAME_TYPES.CROSSWORD:
        return (
          <div className="crossword-question">
            <h2>Crossword Puzzle</h2>
            <p>{question.clue}</p>
            <div className="crossword-grid">
              {question.grid.map((row, rowIndex) => (
                <div key={rowIndex} className="crossword-row">
                  {row.map((cell, cellIndex) => (
                    <div key={cellIndex} className="crossword-cell">
                      {cell || ""}
                    </div>
                  ))}
                </div>
              ))}
            </div>
            <input
              type="text"
              value={userAnswer}
              onChange={(e) => setUserAnswer(e.target.value)}
              placeholder="Enter your answer"
              className="answer-input"
              disabled={gamePhase === GAME_PHASES.ANSWER_FEEDBACK}
            />
          </div>
        );

      default:
        return null;
    }
  };

  const renderFeedback = () => {
    if (gamePhase !== GAME_PHASES.ANSWER_FEEDBACK) return null;

    return (
      <div
        className={`answer-feedback ${
          isCorrectAnswer ? "correct" : "incorrect"
        }`}
      >
        {isCorrectAnswer ? "✓ Correct!" : "✗ Incorrect!"}
        {!isCorrectAnswer && (
          <div style={{ marginTop: "10px", fontSize: "1rem" }}>
            Correct answer:{" "}
            {questions[currentQuestion].correct ||
              questions[currentQuestion].answer}
          </div>
        )}
      </div>
    );
  };

  // Render different screens based on game phase
  if (
    gamePhase === GAME_PHASES.INITIAL_COUNTDOWN ||
    gamePhase === GAME_PHASES.NEXT_QUESTION_COUNTDOWN
  ) {
    return (
      <div className="countdown-container">
        <div className="countdown-display">
          <h1 className="countdown-number">{countdown}</h1>
          <p className="countdown-text">
            {gamePhase === GAME_PHASES.INITIAL_COUNTDOWN
              ? "Game Starts In"
              : "Next Question"}
          </p>
        </div>
      </div>
    );
  }

  if (gamePhase === GAME_PHASES.COMPLETED) {
    return (
      <div className="game-completed">
        <h1>Game Completed!</h1>
        <p>Your Score: {score}</p>
        <button
          onClick={() =>
            navigate("/score-popup", {
              state: { score, userDetails, gameType },
            })
          }
        >
          See Results
        </button>
      </div>
    );
  }

  return (
    <div className="game-page-container">
      {/* Header */}
      <div className="game-header">
        <div className="user-info">
          <span>
            <strong>Name:</strong> {userDetails?.name || "Unknown"}
          </span>
          <span>
            <strong>School:</strong> {userDetails?.school || "Unknown"}
          </span>
        </div>
        <div className="game-info">
          <span>
            <strong>Question:</strong> {currentQuestion + 1}/{questions.length}
          </span>
          <span className="timer">
            <strong>Time:</strong> {timer}s
          </span>
          <span>
            <strong>Score:</strong> {score}
          </span>
        </div>
      </div>

      {/* Question Area */}
      <div className="question-area">
        {renderQuestion()}
        {renderFeedback()}
      </div>

      {/* Submit Button - Only show during active question phase */}
      {gamePhase === GAME_PHASES.QUESTION_ACTIVE && (
        <div className="submit-section">
          <button
            className="submit-btn"
            onClick={handleSubmit}
            disabled={
              (!userAnswer && !selectedOption) ||
              (gameType === GAME_TYPES.CROSSWORD && !userAnswer)
            }
          >
            Submit Answer
          </button>
        </div>
      )}
    </div>
  );
};

export default GamePage;
